function stableUnique<T>(values: readonly T[], key: (v: T) => string): T[] {
  const seen = new Set<string>();
  const result: T[] = [];

  for (const value of values) {
    const k = key(value);
    if (!seen.has(k)) {
      seen.add(k);
      result.push(value);
    }
  }

  return result;
}

// Assertions
const arr1 = [{ id: 1, name: 'Alice' }, { id: 2, name: 'Bob' }, { id: 1, name: 'Alicia' }];
const result1 = stableUnique(arr1, v => v.id.toString());
console.assert(result1.length === 2, 'Should keep first two unique items by id');
console.assert(result1[0].name === 'Alice' && result1[1].name === 'Bob', 'Should preserve first occurrence order');

const arr2 = ['apple', 'banana', 'apricot', 'blueberry'];
const result2 = stableUnique(arr2, s => s[0]);
console.assert(result2.length === 2, 'Should keep first two unique items by first letter');
console.assert(result2[0] === 'apple' && result2[1] === 'banana', 'Should preserve first occurrence order by first letter');
