import React, { useState } from 'react';

interface CounterProps {
  initial?: number;
  onChange?: (value: number) => void;
}

export const Counter: React.FC<CounterProps> = ({ initial = 0, onChange }) => {
  const [count, setCount] = useState(initial);

  const handleIncrement = () => {
    if (count < 10) {
      const newValue = count + 1;
      setCount(newValue);
      onChange?.(newValue);
    }
  };

  const handleDecrement = () => {
    if (count > 0) {
      const newValue = count - 1;
      setCount(newValue);
      onChange?.(newValue);
    }
  };

  return (
    <div className="flex items-center gap-2">
      <button
        onClick={handleDecrement}
        disabled={count === 0}
        className="px-3 py-1 bg-gray-200 rounded disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-300"
      >
        -
      </button>
      <span className="w-8 text-center font-medium">{count}</span>
      <button
        onClick={handleIncrement}
        disabled={count === 10}
        className="px-3 py-1 bg-gray-200 rounded disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-300"
      >
        +
      </button>
    </div>
  );
};
```

**Bug:** `forEach` doesn’t wait for async callbacks, so `out` is returned *before* any fetches complete (it’s usually empty). Also, `fetch` returns a `Response`, not the data—likely you want `.json()` or `.text()`.

**Concise fix (preserving order):**
```js
async function f(urls) {
  return Promise.all(urls.map(async u => {
    const res = await fetch(u);
    return res.json(); // or res.text()
  }));
}
```

*Why this works:* `Promise.all` with `map` runs all fetches in parallel, waits for all to finish, and preserves the order of `urls` in the result array.

